import{_ as i,r as t,o as l,c as r,e as a,a as n,s as e}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Inspector Types - October CMS - 4.x","titleTemplate":false,"description":"Learn how to define component properties.","frontmatter":{"subtitle":"Learn how to define component properties."},"headers":[{"level":2,"title":"Available Types","slug":"available-types","link":"#available-types","children":[]},{"level":2,"title":"Available Configuration","slug":"available-configuration","link":"#available-configuration","children":[]},{"level":2,"title":"Validation Rules","slug":"validation-rules","link":"#validation-rules","children":[{"level":3,"title":"Required Validator","slug":"required-validator","link":"#required-validator","children":[]},{"level":3,"title":"Regex Validator","slug":"regex-validator","link":"#regex-validator","children":[]},{"level":3,"title":"Integer Validator","slug":"integer-validator","link":"#integer-validator","children":[]},{"level":3,"title":"Float Validator","slug":"float-validator","link":"#float-validator","children":[]},{"level":3,"title":"Length Validator","slug":"length-validator","link":"#length-validator","children":[]}]}],"relativePath":"4.x/element/inspector-types.md","filePath":"4.x/element/inspector-types.md"}'),c={name:"4.x/element/inspector-types.md"};function d(u,s,g,k,h,m){const o=t("pre-heading"),p=t("post-heading");return l(),r("div",null,[a(o),s[0]||(s[0]=n("h1",null,"Inspector Types",-1)),a(p),s[1]||(s[1]=e(`<p>Inspector Types are property types used by CMS components. These are referenced by the following areas:</p><ul><li><a href="./../extend/cms-components.html">CMS Component Classes</a></li></ul><p>All inspector types are identified as their individual <strong>type</strong> property.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Max Items&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="available-types"><a href="#available-types" class="header-anchor">#</a> Available Types</h2><p>The following inspector types are available:</p>`,6)),s[2]||(s[2]=n("div",{class:"content-list-p",markdown:"1"},[n("p",null,[n("a",{href:"./inspector/type-string.html"},"String"),n("a",{href:"./inspector/type-stringlist.html"},"String List"),n("a",{href:"./inspector/type-stringlistautocomplete.html"},"String List Autocomplete"),n("a",{href:"./inspector/type-text.html"},"Text"),n("a",{href:"./inspector/type-autocomplete.html"},"Autocomplete"),n("a",{href:"./inspector/type-checkbox.html"},"Checkbox"),n("a",{href:"./inspector/type-dropdown.html"},"Dropdown"),n("a",{href:"./inspector/type-dictionary.html"},"Dictionary"),n("a",{href:"./inspector/type-object.html"},"Object"),n("a",{href:"./inspector/type-objectlist.html"},"Object List"),n("a",{href:"./inspector/type-set.html"},"Set"),n("a",{href:"./inspector/type-table.html"},"Table"),n("a",{href:"./inspector/type-mediafinder.html"},"Media Finder")])],-1)),s[3]||(s[3]=e(`<h2 id="available-configuration"><a href="#available-configuration" class="header-anchor">#</a> Available Configuration</h2><p>The property parameters are defined with an array with the following keys.</p><div class="table"><table tabindex="0"><thead><tr><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>required, the property title, it is used by the component Inspector in the CMS backend.</td></tr><tr><td><strong>description</strong></td><td>required, the property description, it is used by the component Inspector in the CMS backend.</td></tr><tr><td><strong>default</strong></td><td>optional, the default property value to use when the component is added to a page or layout in the CMS backend.</td></tr><tr><td><strong>type</strong></td><td>specifies the property type, which defines how the property is displayed in the Inspector.</td></tr><tr><td><strong>validation</strong></td><td>optional, specifies validation rules for the property value (see below).</td></tr><tr><td><strong>placeholder</strong></td><td>optional placeholder for string and dropdown properties.</td></tr><tr><td><strong>options</strong></td><td>optional array of options for dropdown properties.</td></tr><tr><td><strong>optionsMethod</strong></td><td>specify a method name on the component class to source options.</td></tr><tr><td><strong>depends</strong></td><td>an array of property names a dropdown property depends on. See the <a href="./inspector/type-dropdown.html">dropdown type</a> for more information.</td></tr><tr><td><strong>group</strong></td><td>an optional group name. Groups create sections in the Inspector simplifying the user experience. Use a same group name in multiple properties to combine them.</td></tr><tr><td><strong>showExternalParam</strong></td><td>specifies visibility of the external parameter editor for the property in the Inspector. Default: <code>true</code>. Not supported by the object, objectList, dictionary, set, stringList and stringListAutocomplete types.</td></tr><tr><td><strong>ignoreIfDefault</strong></td><td>set to <code>true</code> to exclude the output from the array if the selection matches default value. Default: <code>false</code></td></tr><tr><td><strong>ignoreIfEmpty</strong></td><td>set to <code>true</code> to exclude the output from the array if the selection has an empty value. Default: <code>false</code></td></tr><tr><td><strong>sortOrder</strong></td><td>specify a custom position as an integer for the property in the available list.</td></tr></tbody></table></div><h2 id="validation-rules"><a href="#validation-rules" class="header-anchor">#</a> Validation Rules</h2><p>Inspector types support several validation rules that can be applied to properties. Validation rules can be applied to top-level properties as well as to internal property definitions of object and object list editors.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Name&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;required&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Name field is required&#39;</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;regex&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Name field can contain only Latin letters.&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;pattern&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;^[a-zA-Z]+$&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The key value in the <code>validation</code> object refers to a validator (see below). Validators are configured with objects, which properties depend on a validator. One property - <code>message</code> is common for all validators.</p><h3 id="required-validator"><a href="#required-validator" class="header-anchor">#</a> Required Validator</h3><p>The <code>required</code> validator checks if a value is not empty. The validator can be used with any editor, including complex editors (sets, dictionaries, object lists, etc.). Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Name&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;required&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Name field is required&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="regex-validator"><a href="#regex-validator" class="header-anchor">#</a> Regex Validator</h3><p>The <code>regex</code> validator validates string values with a regular expression. The validator can be used only with string-typed editors. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Name&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;regex&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Name field can contain only Latin letters&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;pattern&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;^[a-z]+$&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;modifiers&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;i&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The regular expression is specified with the required <code>pattern</code> parameter. The <code>modifiers</code> parameter is optional and can be used for setting regular expression modifiers.</p><h3 id="integer-validator"><a href="#integer-validator" class="header-anchor">#</a> Integer Validator</h3><p>The <code>integer</code> validator checks if the value is integer and can optionally validate if the value is within a specific interval. The validator can be used only with string-typed editors. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;numOfColumns&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Number of Columns&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;integer&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Number of Columns field should contain an integer value&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;allowNegative&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;min&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                        <span class="token string single-quoted-string">&#39;value&#39;</span> <span class="token operator">=&gt;</span> <span class="token operator">-</span><span class="token number">10</span><span class="token punctuation">,</span>
                        <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The number of columns should not be less than -10.&#39;</span>
                    <span class="token punctuation">]</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;max&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                        <span class="token string single-quoted-string">&#39;value&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
                        <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The number of columns should not be greater than 10.&#39;</span>
                    <span class="token punctuation">]</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Supported parameters:</p><ul><li><code>allowNegative</code> - optional, determines if negative values are allowed. By default negative values are not allowed.</li><li><code>min</code> - optional object, defines the minimum allowed value and error message. Object fields: <ul><li><code>value</code> - defines the minimum value.</li><li><code>message</code> - optional, defines the error message.</li></ul></li><li><code>max</code> - optional object, defines the maximum allowed value and error message. Object fields: <ul><li><code>value</code> - defines the maximum value.</li><li><code>message</code> - optional, defines the error message.</li></ul></li></ul><h3 id="float-validator"><a href="#float-validator" class="header-anchor">#</a> Float Validator</h3><p>The <code>float</code> validator checks if the value is a floating point number. The parameters for this validator match the parameters of the <strong>integer</strong> validator described above. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;amount&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Amount&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;float&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Amount field should contain a positive floating point value&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Valid floating point number formats:</p><ul><li>10</li><li>10.302</li><li>-10 (if <code>allowNegative</code> is <code>true</code>)</li><li>-10.84 (if <code>allowNegative</code> is <code>true</code>)</li></ul><h3 id="length-validator"><a href="#length-validator" class="header-anchor">#</a> Length Validator</h3><p>The <code>length</code> validator checks if a string, array or object is not shorter or longer than specified values. This validator can work with the string, text, set, string list, dictionary and object list editors. In multiple-value editors (set, string list, dictionary and object list) it validates the number of items created in the editor.</p><div class="custom-block tip"><p>The <code>length</code> validator doesn&#39;t validate empty values. For example, if it&#39;s applied to a set editor, and the set is empty, the validation will pass regardless of the <code>min</code> and <code>max</code> parameter values. Use the <code>required</code> validator together with the <code>length</code> validator to make sure that the value is not empty before the length validation is applied.</p></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Name&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;length&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;min&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                        <span class="token string single-quoted-string">&#39;value&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">2</span><span class="token punctuation">,</span>
                        <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The name should not be shorter than two letters.&#39;</span>
                    <span class="token punctuation">]</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;max&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                        <span class="token string single-quoted-string">&#39;value&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
                        <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The name should not be longer than 10 letters.&#39;</span>
                    <span class="token punctuation">]</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Supported parameters:</p><ul><li><code>min</code> - optional object, defines the minimum allowed length and error message. Object fields: <ul><li><code>value</code> - defines the minimum value.</li><li><code>message</code> - optional, defines the error message.</li></ul></li><li><code>max</code> - optional object, defines the maximum allowed length and error message. Object fields: <ul><li><code>value</code> - defines the maximum value.</li><li><code>message</code> - optional, defines the error message.</li></ul></li></ul>`,30))])}const y=i(c,[["render",d]]);export{v as __pageData,y as default};
